// Yggdrasil as the structure store under every spark_dsg graph (patches/spark_dsg/0002).
// Selected with SPARK_DSG_BACKEND=yggdrasil|both once this library is loaded (LD_PRELOAD).
#include <spark_dsg/graph_backend.h>

#include <vector>

#include "ygg_bridge_cxx/lib.h"  // generated by corrosion_add_cxxbridge

namespace hydra_ygg {
namespace {

using spark_dsg::LayerKey;
using spark_dsg::NodeId;

int64_t pack(const LayerKey& key) {
  return static_cast<int64_t>(key.layer) * 1000 + key.partition;
}

rust::Box<Topology> makeTopology(const std::set<LayerKey>& layers) {
  std::vector<int64_t> keys;
  for (const auto& key : layers) {
    keys.push_back(pack(key));
  }
  return new_topology(rust::Slice<const int64_t>(keys.data(), keys.size()));
}

class YggdrasilGraphBackend : public spark_dsg::GraphBackend {
 public:
  explicit YggdrasilGraphBackend(const std::set<LayerKey>& layers)
      : topology_(makeTopology(layers)) {}

  void nodeAdded(NodeId node, LayerKey layer, const Eigen::Vector3d& p) override {
    topology_->add_node(node, pack(layer), true, p.x(), p.y(), p.z());
  }
  void nodeRemoved(NodeId node) override { topology_->remove_node(node); }
  void edgeAdded(NodeId source, NodeId target) override { topology_->add_edge(source, target); }
  void edgeRemoved(NodeId source, NodeId target) override {
    topology_->remove_edge(source, target);
  }
  void cleared() override { topology_->clear(); }

  bool hasNode(NodeId node) const override { return topology_->has_node(node); }
  bool hasEdge(NodeId source, NodeId target) const override {
    return topology_->has_edge(source, target);
  }
  size_t numNodes() const override { return topology_->num_nodes(); }
  size_t numEdges() const override { return topology_->num_edges(); }

 private:
  rust::Box<Topology> topology_;
};

const bool registered = [] {
  spark_dsg::GraphBackend::factory() = [](const std::set<LayerKey>& layers) {
    return spark_dsg::GraphBackend::Ptr(new YggdrasilGraphBackend(layers));
  };
  return true;
}();

}  // namespace
}  // namespace hydra_ygg
